def best_trade(prices):
    best = 0
    low = None
    for p in prices:
        if low is None or p < low:
            low = p
        elif p - low > best:
            best = p - low
    return best

def copies_fixed(n, step):
    capacity, size, copies = step, 0, 0
    for _ in range(n):
        if size == capacity:
            capacity += step
            copies += size
        size += 1
    return copies
